CREATE TABLE official_classification_restoration (revision TEXT NOT NULL, service_id TEXT NOT NULL, field TEXT NOT NULL CHECK(field IN ('type','subcategory')), expected_name TEXT NOT NULL, expected_updated_date TEXT NOT NULL, before_value TEXT NOT NULL, after_value TEXT NOT NULL, source_label TEXT NOT NULL, source_url TEXT NOT NULL, physical_page INTEGER NOT NULL, glyph_sha256 TEXT NOT NULL, PRIMARY KEY(revision,service_id,field));
